31	        if (node == null) {
32	            return;
33	        }
34	
35	        int nextSpace = space + PRINT_INDENT;
36	        appendTree(node.right(), nextSpace, builder);
37	        builder.append('\n');
38	        for (int i = PRINT_INDENT; i < nextSpace; i++) {
39	            builder.append(' ');
40	        }
41	        builder.append(node.data()).append('\n');
42	        appendTree(node.left(), nextSpace, builder);
