 1	final class RedBlackTreeValidator {
 2	    private RedBlackTreeValidator() {
 3	    }
 4	
 5	    static boolean isValid(RedBlackTreeSnapshot snapshot) {
 6	        RedBlackTreeSnapshot.NodeSnapshot root = snapshot.root();
 7	        if (root == null) {
 8	            return true;
 9	        }
10	
11	        if (root.color() != RedBlackTreeColor.BLACK) {
12	            return false;
13	        }
14	
15	        return isBinarySearchTree(root, Long.MIN_VALUE, Long.MAX_VALUE)
16	            && hasNoRedRedViolation(root)
17	            && blackHeight(root) != -1;
18	    }
19	
20	    private static boolean isBinarySearchTree(
21	        RedBlackTreeSnapshot.NodeSnapshot node,
22	        long minInclusive,
23	        long maxExclusive
24	    ) {
25	        if (node == null) {
26	            return true;
27	        }
28	
29	        if (node.data() < minInclusive || node.data() >= maxExclusive) {
30	            return false;
31	        }
32	
33	        return isBinarySearchTree(node.left(), minInclusive, node.data())
34	            && isBinarySearchTree(node.right(), node.data(), maxExclusive);
35	    }
36	
37	    private static boolean hasNoRedRedViolation(RedBlackTreeSnapshot.NodeSnapshot node) {
38	        if (node == null) {
39	            return true;
40	        }
41	
42	        if (isRed(node) && (isRed(node.left()) || isRed(node.right()))) {
43	            return false;
44	        }
45	
46	        return hasNoRedRedViolation(node.left()) && hasNoRedRedViolation(node.right());
47	    }
48	
49	    private static int blackHeight(RedBlackTreeSnapshot.NodeSnapshot node) {
50	        if (node == null) {
51	            return 1;
52	        }
53	
54	        int leftHeight = blackHeight(node.left());
55	        int rightHeight = blackHeight(node.right());
56	        if (leftHeight == -1 || rightHeight == -1 || leftHeight != rightHeight) {
57	            return -1;
58	        }
59	
60	        return leftHeight + (node.color() == RedBlackTreeColor.BLACK ? 1 : 0);
61	    }
62	
63	    private static boolean isRed(RedBlackTreeSnapshot.NodeSnapshot node) {
64	        return node != null && node.color() == RedBlackTreeColor.RED;
65	    }
66	}

